#include <bits/stdc++.h>
using namespace std;

// 功能函数：Kahn 拓扑排序（小根堆）
vector<int> findOrder(int n, const vector<pair<int,int>>& pairs) {
    vector<vector<int>> g(n);
    vector<int> indeg(n, 0);
    for (auto &e : pairs) {
        int a = e.first, b = e.second; // b -> a
        if (0 <= a && a < n && 0 <= b && b < n) {
            g[b].push_back(a);
            indeg[a]++;
        }
    }
    priority_queue<int, vector<int>, greater<int>> pq;
    for (int i = 0; i < n; ++i) if (indeg[i] == 0) pq.push(i);

    vector<int> ans; ans.reserve(n);
    while (!pq.empty()) {
        int u = pq.top(); pq.pop();
        ans.push_back(u);
        for (int v : g[u]) {
            if (--indeg[v] == 0) pq.push(v);
        }
    }
    if ((int)ans.size() < n) return {}; // 有环，无解
    return ans;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    // 读整段输入
    string all, line;
    while (getline(cin, line)) { all += line; all += '\n'; }

    // 把 '[', ']', ',' 全部替换成空格；然后流式读所有整数
    for (char &c : all) {
        if (c == '[' || c == ']' || c == ',') c = ' ';
    }
    stringstream ss(all);
    vector<long long> nums;
    long long x;
    while (ss >> x) nums.push_back(x);

    int n = 0;
    vector<pair<int,int>> pairs;
    if (!nums.empty()) {
        n = (int)nums.back();                       // 最后一个是 n
        for (size_t i = 0; i + 2 <= nums.size() - 1; i += 2) {
            pairs.push_back({(int)nums[i], (int)nums[i + 1]});
        }
    }

    auto ans = findOrder(n, pairs);

    cout << "[";
    for (size_t i = 0; i < ans.size(); ++i) {
        if (i) cout << ",";
        cout << ans[i];
    }
    cout << "]";
    return 0;
}
